package com.ecommerce.service;
import com.ecommerce.dto.*; import com.ecommerce.entity.Cliente; import com.ecommerce.entity.Usuario; import com.ecommerce.enums.Rol; import com.ecommerce.exception.BadRequestException; import com.ecommerce.repository.ClienteRepository; import com.ecommerce.repository.UsuarioRepository; import com.ecommerce.security.JwtService; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.security.core.userdetails.UserDetailsService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService {
 private final UsuarioRepository usuarioRepository; private final ClienteRepository clienteRepository; private final PasswordEncoder encoder; private final JwtService jwt; private final UserDetailsService uds;
 public AuthService(UsuarioRepository u,ClienteRepository c,PasswordEncoder e,JwtService j,UserDetailsService uds){this.usuarioRepository=u;this.clienteRepository=c;this.encoder=e;this.jwt=j;this.uds=uds;}
 @Transactional public AuthResponse registrar(RegistroRequest r){ if(usuarioRepository.existsByEmail(r.getEmail().trim().toLowerCase())) throw new BadRequestException("El email ya esta registrado"); Usuario u=new Usuario();u.setNombre(r.getNombre().trim());u.setEmail(r.getEmail().trim().toLowerCase());u.setPassword(encoder.encode(r.getPassword()));u.setRol(Rol.CLIENTE);u=usuarioRepository.save(u); Cliente c=new Cliente();c.setUsuario(u);c.setDireccion(r.getDireccion().trim());c.setTelefono(r.getTelefono().trim());clienteRepository.save(c);return response(u); }
 @Transactional(readOnly=true) public AuthResponse login(LoginRequest r){ Usuario u=usuarioRepository.findByEmail(r.getEmail().trim().toLowerCase()).orElseThrow(()->new BadRequestException("Credenciales invalidas")); if(!encoder.matches(r.getPassword(),u.getPassword())) throw new BadRequestException("Credenciales invalidas"); return response(u); }
 private AuthResponse response(Usuario u){ UserDetails d=uds.loadUserByUsername(u.getEmail()); return new AuthResponse(jwt.generarToken(d),u.getEmail(),u.getNombre(),u.getRol().name()); }
}
